rejected_cache.focused_tests:
use super::*;
use std::{sync::mpsc as sync_channel, time::Duration};

fn relay() -> Arc<Relay> {
    Relay::new(Config {
        auth_password: Some("cache-test".into()),
        ..Config::default()
    })
    .unwrap()
}

fn joined(relay: &Arc<Relay>, channel: &[u8]) -> Subscription {
    let mut sub = relay.subscribe(channel).unwrap();
    let id = sub.registration.peer.id.load(Relaxed);
    take(&mut sub, &protocol::uint(id));
    sub
}

fn take(sub: &mut Subscription, expected: &[u8]) {
    let packet = sub.outgoing.try_recv().unwrap();
    assert_eq!(packet.frame.to_vec(), expected);
}

fn empty(sub: &mut Subscription) {
    assert!(matches!(
        sub.outgoing.try_recv(),
        Err(mpsc::error::TryRecvError::Empty)
    ));
}

fn command(relay: &Arc<Relay>, sub: &mut Subscription, op: u8, value: &[u8]) {
    relay
        .receive(&sub.registration.peer, protocol::request(op, value))
        .unwrap();
    let response = if op == 0 { &[0xf5][..] } else { value };
    take(sub, &protocol::reply(op, response));
}

fn authenticate(relay: &Arc<Relay>, sub: &mut Subscription) {
    command(relay, sub, 0, &protocol::text("cache-test"));
}

fn send(relay: &Arc<Relay>, cache: &mut RecipientCache, source: &Subscription, id: u64) {
    let bytes = protocol::envelope(id, b"\x43abc");
    relay
        .receive_with_storage(&source.registration.peer, bytes, 4096, cache)
        .unwrap();
}

fn delivery(source: &Subscription) -> Bytes {
    protocol::envelope(source.registration.peer.id.load(Relaxed), b"\x43abc")
}

#[test]
fn warmed_private_route_completes_while_registry_is_exclusively_held() {
    let relay = relay();
    let source = joined(&relay, b"source");
    let mut target = joined(&relay, b"target");
    let id = target.registration.peer.id.load(Relaxed);
    let mut cache = RecipientCache::default();
    send(&relay, &mut cache, &source, id);
    take(&mut target, &delivery(&source));
    let guard = relay.state.write();
    let peer = source.registration.peer.clone();
    let copy = relay.clone();
    let (done, result) = sync_channel::channel();
    let worker = std::thread::spawn(move || {
        let input = protocol::envelope(id, b"\x43abc");
        let answer = copy.receive_with_storage(&peer, input, 4096, &mut cache);
        done.send(answer).unwrap();
    });
    let answer = result.recv_timeout(Duration::from_secs(2));
    // Always release the lock before joining, including an unexpected miss.
    drop(guard);
    worker.join().unwrap();
    assert_eq!(answer.unwrap().unwrap(), 1);
    take(&mut target, &delivery(&source));
    assert_eq!(relay.metrics.routing_copied_bytes.load(Relaxed), 0);
    assert_eq!(relay.metrics.queued_bytes.load(Relaxed), 0);
}

#[test]
fn cached_id_assignment_and_takeover_follow_the_current_owner() {
    let relay = relay();
    let source = joined(&relay, b"source");
    let mut original = joined(&relay, b"original");
    let mut replacement = joined(&relay, b"replacement");
    authenticate(&relay, &mut original);
    authenticate(&relay, &mut replacement);
    let old = original.registration.peer.id.load(Relaxed);
    let mut cache = RecipientCache::default();
    send(&relay, &mut cache, &source, old);
    take(&mut original, &delivery(&source));
    command(&relay, &mut original, 3, &protocol::uint(42));
    send(&relay, &mut cache, &source, old);
    empty(&mut original);
    send(&relay, &mut cache, &source, 42);
    take(&mut original, &delivery(&source));
    command(&relay, &mut replacement, 3, &protocol::uint(42));
    assert_eq!(*original.close.borrow(), Some(Disconnect::TAKEN));
    send(&relay, &mut cache, &source, 42);
