struct ReplyProbe {
    relay: Weak<Relay>,
    before: AtomicU64,
    armed: AtomicBool,
    checked: AtomicUsize,
}

impl PeerOutput for ReplyProbe {
    fn send(&self, _: Envelope) -> bool {
        if self.armed.load(Relaxed) {
            assert_ne!(
                self.relay
                    .upgrade()
                    .unwrap()
                    .routing_generation
                    .load(Acquire),
                self.before.load(Relaxed),
                "invalidate a cached route before publishing a mutation reply"
            );
            self.checked.fetch_add(1, Relaxed);
        }
        true
    }
    fn close(&self, _: Disconnect) {}
}

#[test]
fn registry_mutations_invalidate_before_observable_welcome_or_control_output() {
    let relay = relay();
    let output = Arc::new(ReplyProbe {
        relay: Arc::downgrade(&relay),
        before: AtomicU64::new(relay.routing_generation.load(Relaxed)),
        armed: AtomicBool::new(true),
        checked: AtomicUsize::new(0),
    });
    let registration = relay
        .subscribe_with_output(GLOBAL_CHANNEL, output.clone())
        .unwrap();
    output.armed.store(false, Relaxed);
    relay
        .receive(
            &registration.peer,
            protocol::request(0, &protocol::text("cache-test")),
        )
        .unwrap();
    for (op, value) in [
        (3, protocol::uint(42)),
        (1, protocol::uint(u64::from(PRIVATE_MESSAGE))),
    ] {
        output
            .before
            .store(relay.routing_generation.load(Relaxed), Relaxed);
        output.armed.store(true, Relaxed);
        relay
            .receive(&registration.peer, protocol::request(op, &value))
            .unwrap();
        output.armed.store(false, Relaxed);
    }
    assert_eq!(output.checked.load(Relaxed), 3);
}

